const websites = [
  "https://jpcdubai.com/",
  "https://jumarental.com/",
  "https://onlineignou1.neevedu.com/",
];

return websites.map(url => ({ json: { url } }));

const results = $input.all();
const sites = $('Code in JavaScript').all();

const ok = [];
const down = [];

results.forEach((item, i) => {
  const url = sites[i] ? sites[i].json.url : 'Unknown';
  const code = item.json.statusCode;
  const err = item.json.error;

  if (err) {
    const msg = typeof err === 'string' ? err : (err.message || 'Connection error');
    down.push(`DOWN  ${url}  -> ${msg}`);
  } else if (code && (code < 200 || code >= 400)) {
    down.push(`DOWN  ${url}  -> Status ${code}`);
  } else {
    ok.push(`OK    ${url}  (${code || 'OK'})`);
  }
});

const date = $now.toFormat('dd-MM-yyyy hh:mm a');
const total = results.length;

const subject = down.length
  ? `ALERT: ${down.length} website(s) DOWN - ${date}`
  : `All ${total} websites OK - ${date}`;

const report =
  `Website Check Report\nDate: ${date}\n\n` +
  `Total: ${total} | Up: ${ok.length} | Down: ${down.length}\n\n` +
  (down.length ? `--- PROBLEM WALI SITES ---\n${down.join('\n')}\n\n` : '') +
  `--- THEEK CHAL RAHI SITES ---\n${ok.join('\n') || '(none)'}`;

return [{ json: { total, upCount: ok.length, downCount: down.length, subject, report } }];
